pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime1, uint256 unlockTime2) public {
        // Keep amounts within reasonable bounds and non-zero to avoid trivial vacuously true cases
        vm.assume(amount1 > 0 && amount1 <= 1000 ether);
        vm.assume(amount2 > 0 && amount2 <= 1000 ether);
        // unlock times within reasonable range
        vm.assume(unlockTime1 <= type(uint64).max && unlockTime2 <= type(uint64).max);
        // Two distinct actors
        address alice = address(0x1000);
        address bob = address(0x2000);
        // Fund actors
        vm.deal(alice, amount1 + amount2);
        vm.deal(bob, amount1 + amount2);

        // Alice: Put with unlockTime1
        vm.prank(alice);
        c.Put{value: amount1}(unlockTime1);
        // Bob: Put with unlockTime2
        vm.prank(bob);
        c.Put{value: amount2}(unlockTime2);

        // Warp past both unlock times to allow collections
        vm.warp(block.timestamp + type(uint64).max + 1);
        // Alice collects half of her balance back
        vm.prank(alice);
        c.Collect(amount1 / 2);
        // Bob collects a third of his balance back
        vm.prank(bob);
        c.Collect(amount2 / 3);

        // The rule: for all addresses, the sum of all user balances in the tracking mapping equals the contract's balance
        uint256 sumUserBalances = c.Acc(alice) + c.Acc(bob);
        uint256 contractBalance = address(c).balance;
        assertTrue(sumUserBalances == contractBalance);
    }
}

