pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 putAmount, uint256 collectAmount, uint256 unlockTime) public {
        // Keep amounts in a reasonable range
        vm.assume(putAmount > 0 && putAmount <= 100 ether);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);
        vm.assume(unlockTime <= type(uint256).max - 1);

        address alice = address(0x1000);
        vm.deal(alice, putAmount);

        // Alice puts Ether
        vm.prank(alice);
        c.Put{value: putAmount}(unlockTime);

        // Warp past unlock time
        uint256 targetTime = unlockTime > block.timestamp ? unlockTime + 1 : block.timestamp + 1;
        vm.warp(targetTime);

        // Alice collects
        vm.prank(alice);
        try c.Collect(collectAmount) { } catch { }

        // Property: contract balance + alice's collected amount (if successful) equals her recorded balance
        // Actually, after collect, contract balance should be putAmount - collectAmount
        // And alice's Acc balance should be putAmount - collectAmount
        // Since collect may fail if conditions aren't met, we check a universal invariant:
        // contract balance >= 0 and Acc[alice].balance <= address(c).balance (if unlock conditions met)
        // But simpler: After operations, sum of all user balances + pending payouts = contract balance
        // Here just alice: Acc[alice].balance == address(c).balance
        ( , uint256 bal) = c.Acc(alice);
        assertTrue(bal == address(c).balance);
    }
}

