pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 putAmount, uint256 collectAmount, uint256 unlockTime) public {
        // Restrict to admissible domain: amounts >= 0 and putAmount > 0 to actually attempt a Put
        vm.assume(putAmount > 0);
        vm.assume(collectAmount <= putAmount);
        // Ensure unlockTime is in the past so Collect is not time-blocked
        vm.assume(unlockTime <= block.timestamp);

        address user = address(0x1234);
        vm.deal(user, putAmount);
        vm.prank(user);
        c.Put{value: putAmount}(unlockTime);

        // Now attempt to collect the amount
        vm.prank(user);
        try c.Collect(collectAmount) {
            // If Collect succeeds, the balance MUST remain >= 0 (no underflow)
            (uint256 unlo, uint256 bal) = c.Acc(user);
            assertTrue(bal < type(uint256).max / 2); // underflow would produce a huge balance
        } catch {
            // If Collect reverts, the invariant is vacuously true (no underflow occurred)
            assertTrue(true);
        }
    }
}

