pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime1, uint256 unlockTime2, address user) public {
        // 1. Bound amounts to admissible domain: non-zero and not causing overflow.
        //    MinSum is 1 ether, so we keep amounts reasonable.
        amount1 = bound(amount1, 1 ether, 1000 ether);
        amount2 = bound(amount2, 1 ether, 1000 ether);
        // Ensure unlock times are in the past so Collect doesn't interfere; block.timestamp is used as floor in Put.
        // To keep the test focused on Put balance updates, we set unlockTime far in the past.
        unlockTime1 = bound(unlockTime1, 0, block.timestamp - 1);
        unlockTime2 = bound(unlockTime2, 0, block.timestamp - 1);
        // avoid address(0) or the c address itself as user
        vm.assume(user != address(0) && user != address(c) && user != address(this));

        // 2. Set up balance for user
        vm.deal(user, amount1 + amount2);

        // First Put call
        vm.prank(user);
        c.Put{value: amount1}(unlockTime1);

        // Second Put call
        vm.prank(user);
        c.Put{value: amount2}(unlockTime2);

        // 3. Assert: the user's Acc balance equals total ether sent.
        ( , uint accBalance) = c.Acc(user);
        assertEq(accBalance, amount1 + amount2, "Acc balance must equal sum of deposited amounts after two Put calls");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime1, uint256 unlockTime2, address user) public {
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 <= type(uint256).max / 2 && amount2 <= type(uint256).max / 2);
        vm.assume(unlockTime1 <= type(uint256).max - block.timestamp && unlockTime2 <= type(uint256).max - block.timestamp);
        vm.assume(user != address(this) && user != address(0));

        vm.deal(user, amount1 + amount2);
        vm.prank(user);
        c.Put{value: amount1}(unlockTime1);

        vm.prank(user);
        try c.Put{value: amount2}(unlockTime2) {} catch {}

        uint256 balance = c.Acc(user).balance;
        assertTrue(balance == amount1 + amount2);
    }
}
